const { scrypt, scryptSync } = require('node:crypto');
const { performance } = require('node:perf_hooks');
const { promisify } = require('node:util');
async function measure(kind) {
  let firstHeartbeat = null;
  const started = performance.now();
  const beat = setInterval(() => { if (firstHeartbeat === null) firstHeartbeat = performance.now() - started; }, 1);
  if (kind === 'sync') {
    for (let i = 0; i < 8; i++) scryptSync('Synthetic-test-password-123', '12'.repeat(16), 64);
  } else {
    for (let i = 0; i < 8; i++) await promisify(scrypt)('Synthetic-test-password-123', '12'.repeat(16), 64);
  }
  const elapsed = performance.now() - started;
  await new Promise(resolve => setTimeout(resolve, 10));
  clearInterval(beat);
  return { mode: kind, elapsedMs: Number(elapsed.toFixed(1)), firstHeartbeatMs: Number(firstHeartbeat.toFixed(1)) };
}
(async () => { console.log(JSON.stringify([await measure('sync'), await measure('async')])); })();
